#include <iostream>
#include <vector>
#include <cassert>

using namespace std;

typedef long long ll;

const int MOD = 1000000007;

using Matrix = vector<vector<int>>;

vector<Matrix> dp_levels;
Matrix tmp_matrix;
Matrix start_base;

Matrix rotate(const Matrix &mat, int shift)
{
    int size = (int)mat.size() - 1;
    shift = (size - shift) % size;
    Matrix result = mat;
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            result[i][j] = mat[(i + shift) % size][(j + shift) % size];
        }
    }
    for (int j = 0; j < size; ++j) {
        result[size][j] = mat[size][(j + shift) % size];
    }
    return result;
}

Matrix multiply(const Matrix &a, const Matrix &b)
{
    int n = (int)a.size(), k = (int)a[0].size(), m = (int)b[0].size();
    vector<vector<int>> A(n, vector<int>(k));
    vector<vector<int>> B(k, vector<int>(m));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < k; ++j)
            A[i][j] = a[i][j];
    for (int i = 0; i < k; ++i)
        for (int j = 0; j < m; ++j)
            B[i][j] = b[i][j];
    Matrix res(n, vector<int>(m, 0));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            for (int l = 0; l < k; ++l)
                res[i][j] = (res[i][j] + (long long)A[i][l] * B[l][j]) % MOD;
    return res;
}

int main()
{
    ll n;
    int k;
    cin >> n >> k;
    int max_depth = 0;
    {
        ll temp = n;
        while (temp != 0) {
            ++max_depth;
            temp /= k;
        }
    }
    dp_levels.resize(max_depth);
    {
        dp_levels[0].assign(k + 1, vector<int>(k + 1, 0));
        for (int i = 0; i <= k; ++i)
            for (int j = 0; j <= k; ++j)
                dp_levels[0][i][j] = (i == j || j == 0);
        Matrix identity(k + 1, vector<int>(k + 1, 0));
        for (int i = 0; i <= k; ++i)
            identity[i][i] = 1;
        for (int depth = 1; depth < max_depth; ++depth) {
            dp_levels[depth] = identity;
            Matrix prev = dp_levels[depth - 1];
            int current_x = k;
            for (int i = 0; (1 << i) <= current_x; ++i) {
                if (current_x & (1 << i)) {
                    dp_levels[depth] = prev * rotate(dp_levels[depth], (1 << i));
                    current_x ^= (1 << i);
                }
                prev = prev * rotate(prev, (1 << i));
            }
        }
    }
    start_base.assign(1, vector<int>(k + 1, 0));
    start_base[0][k] = 1;
    int shift_idx = 0;
    ll val = n;
    vector<int> digits;
    while (val != 0) {
        digits.push_back(val % k);
        val /= k;
    }
    int len = (int)digits.size();
    for (int idx = len - 1; idx >= 0; --idx) {
        int rem = digits[idx];
        for (int it = 0; it < rem; ++it, shift_idx = (shift_idx + 1) % k) {
            start_base = start_base * rotate(dp_levels[idx], shift_idx);
        }
    }
    int total_res = 0;
    for (int i = 0; i <= k; ++i) {
        total_res = (total_res + start_base[0][i]) % MOD;
    }
    cout << total_res << '\n';
    return 0;
}
